// --- Main Logic for "Run Once for Each Item" ---

// The node automatically handles the loop, passing the current item as 'item' (singular).
// We remove the outer loop 'for (const item of items) {'

// Get the country value from the current item
// The variable 'item' is the single item's payload in this mode.
const countryRaw = item.json["Country "]; 

let country = "";
if (countryRaw) {
    // Clean and normalize the country string
    country = countryRaw.toLowerCase().trim();
}

// Define arrays for the different time zone groups (remains the same)
const t1Countries = ["usa", "united states", "canada"];
const europeanCountries = [
    "albania", "andorra", "armenia", "austria", "azerbaijan", "belarus", "belgium",
    "bosnia and herzegovina", "bulgaria", "croatia", "cyprus", "czech republic", "czechia",
    "denmark", "estonia", "finland", "france", "georgia", "germany", "greece", "hungary",
    "iceland", "ireland", "italy", "kosovo", "latvia", "liechtenstein", "lithuania",
    "luxembourg", "malta", "moldova", "monaco", "montenegro", "netherlands", "north macedonia",
    "norway", "poland", "portugal", "romania", "russia", "san marino", "serbia", "slovakia",
    "slovenia", "spain", "sweden", "switzerland", "turkey", "ukraine", "united kingdom",
    "vatican city"
];
const t3Countries = ["australia", "new zealand"];

// Determine and populate the Time Zone based on the country value
if (t1Countries.includes(country)) {
    item.json["Time Zone"] = "T1";
} else if (europeanCountries.includes(country)) {
    item.json["Time Zone"] = "T2";
} else if (t3Countries.includes(country)) {
    item.json["Time Zone"] = "T3";
} else {
    item.json["Time Zone"] = "T4";
}

// Return the modified single item.
// This is the correct return structure for "Run Once for Each Item" mode.
return item;

// Function to generate a random 6-character alphanumeric token
function generateAlphaNumericToken() {
  const characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  let token = '';
  for (let i = 0; i < 6; i++) {
    const randomIndex = Math.floor(Math.random() * characters.length);
    token += characters[randomIndex];
  }
  return token;
}

// --- Main Logic for "Run Once for Each Item" ---

// The node automatically handles the loop, passing the current item as 'item'.
// Access the JSON payload of the CURRENT item.
// Note: If the input variable is 'item' (singular), there is no 'items[i]' or 'items.length'.

// Add the token parameter to the current item's JSON data
item.json.token = generateAlphaNumericToken();

// Return the modified single item. 
// When running "Run Once for Each Item," the code must return a single item (dictionary/object), 
// NOT an array of items, which is handled implicitly by the node's loop.
return item;

